import Team from "./team";

function TeamsList({ teams }) {
	return (
		<main>
			<table>
				<thead className="table-head">
					<tr>
						<th className="team-name">Teams</th>
						<th>Points</th>
						<th>W</th>
						<th>D</th>
						<th>L</th>
						<th>GF</th>
						<th>GA</th>
						<th>GD</th>
					</tr>
				</thead>
				<tbody className="table-body">
					{teams.map((team) => (
						<Team key={team.id} team={team} />
					))}
				</tbody>
			</table>
		</main>
	);
}
export default TeamsList;
